package report

const page = `<!doctype html>
<html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>LLMOps 比較 {{.ID}}</title><style>
:root{color-scheme:light dark;--bg:#f3f5f7;--card:#fff;--ink:#253444;--muted:#53677b;--border:#d4dfe8;--accent:#315f8b;--code:#edf2f6;--good:#176943;--bad:#9f2c35;--warn:#795914}
@media(prefers-color-scheme:dark){:root{--bg:#111923;--card:#1a2735;--ink:#e5eef7;--muted:#b1c2d3;--border:#354b60;--accent:#acd3fb;--code:#23374a;--good:#8de1b3;--bad:#ffb1b9;--warn:#f1d18b}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.8 -apple-system,BlinkMacSystemFont,'Hiragino Kaku Gothic ProN',sans-serif}main{max-width:1250px;margin:auto;padding:35px 24px 70px}h1{font-size:34px;line-height:1.4;margin:10px 0 15px}h2{font-size:23px;margin:0 0 15px}h3{font-size:18px;margin:0 0 12px}p{margin:10px 0}.eyebrow{font-size:11px;letter-spacing:.12em;color:var(--muted)}.muted{color:var(--muted)}.box,.case{padding:24px;background:var(--card);border:1px solid var(--border);border-radius:12px;margin-top:22px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.side{min-width:0;padding:18px;border:1px solid var(--border);border-radius:9px}.tag{font-size:12px;display:inline-block;border:1px solid var(--border);border-radius:20px;padding:2px 10px;margin:0 6px 6px 0;color:var(--accent)}dl{display:grid;grid-template-columns:115px minmax(0,1fr);gap:5px 12px;margin:10px 0;font-size:13px}dt{color:var(--muted)}dd{margin:0;overflow-wrap:anywhere}pre{background:var(--code);padding:14px;border-radius:7px;font:12px/1.8 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;max-height:450px;overflow:auto}code{font:12px/1.6 ui-monospace,monospace;overflow-wrap:anywhere}.counts{font-size:19px;font-weight:700}.passed{color:var(--good)}.failed{color:var(--bad)}.needs_review,.not_evaluated,.missing{color:var(--warn)}.case-head{display:flex;justify-content:space-between;align-items:start;gap:15px;flex-wrap:wrap}.change{font-weight:700}.state{font-weight:700;font-size:18px}.reason{font-size:13px;overflow-wrap:anywhere}.source{margin-bottom:20px;border-bottom:1px solid var(--border);padding-bottom:14px}summary{cursor:pointer;color:var(--accent);font-size:13px}ul{margin:5px 0;padding-left:20px;font-size:13px}.snapshot{overflow:auto}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border-bottom:1px solid var(--border);padding:8px 12px;text-align:left}th{white-space:nowrap}.hint{font-size:12px;color:var(--muted)}@media(max-width:700px){main{padding:20px 12px 40px}h1{font-size:28px}.grid{grid-template-columns:1fr}.box,.case{padding:17px}.side{padding:14px}dl{grid-template-columns:95px minmax(0,1fr)}}@media print{body{background:white;color:black}.box,.case{break-inside:avoid}pre{max-height:none}.grid{grid-template-columns:1fr 1fr}main{padding:0}}
</style></head><body><main><header><div class="eyebrow">SHARED LLMOPS / IMMUTABLE DATASET COMPARISON</div><h1>現行と候補の比較</h1><span class="tag">{{.ID}}</span><span class="tag">{{.Dataset.AppID}} / {{.Dataset.TaskID}}</span><span class="tag">{{.Mode}} mode</span><p>同じdataset releaseと評価器で比較。待機・実行失敗・結果未記録も全件の分母に残す。</p></header>
<section class="box"><h2>データと評価条件</h2><dl><dt>Dataset release</dt><dd><code>{{.Dataset.ReleaseID}}</code></dd><dt>比較の範囲</dt><dd>{{if eq .Mode "prepared"}}prepared input固定。LLMへの入力を揃えた比較。{{else}}Rawから前処理を含む比較。入力原文と加工版を併記。{{end}}</dd></dl><div class="table-wrap"><table><thead><tr><th>Table</th><th>固定snapshot ID</th></tr></thead><tbody>{{range .Dataset.Snapshots}}<tr><td><code>{{.Table}}</code></td><td><code>{{.ID}}</code></td></tr>{{end}}</tbody></table></div><p class="hint">元データのアクセス権は出力作成前に呼出側で確認する。このHTMLは許可されたartifactから生成した閲覧用の成果物。</p></section>
<section class="box"><h2>実行と採点の件数</h2><div class="grid"><div class="side"><h3>現行</h3>{{with countCurrent}}<div class="counts">全 {{.Total}} 件 / 採点対象 {{.Evaluated}} 件</div><p>合格 {{.Passed}} · 不合格 {{.Failed}} · 人の確認待ち {{.NeedsReview}} · 結果未記録 {{.Missing}}</p>{{end}}{{with .Current}}<dl><dt>Run</dt><dd><code>{{.RunID}}</code></dd><dt>実行経路</dt><dd>{{label .ExecutionSource}}</dd><dt>Prompt</dt><dd>{{.PromptVersion}}</dd><dt>Code</dt><dd>{{.CodeVersion}}</dd><dt>Evaluator</dt><dd>{{.EvaluatorVersion}}</dd></dl>{{end}}</div><div class="side"><h3>候補</h3>{{with countCandidate}}<div class="counts">全 {{.Total}} 件 / 採点対象 {{.Evaluated}} 件</div><p>合格 {{.Passed}} · 不合格 {{.Failed}} · 人の確認待ち {{.NeedsReview}} · 結果未記録 {{.Missing}}</p>{{end}}{{with .Candidate}}<dl><dt>Run</dt><dd><code>{{.RunID}}</code></dd><dt>実行経路</dt><dd>{{label .ExecutionSource}}</dd><dt>Prompt</dt><dd>{{.PromptVersion}}</dd><dt>Code</dt><dd>{{.CodeVersion}}</dd><dt>Evaluator</dt><dd>{{.EvaluatorVersion}}</dd></dl>{{end}}</div></div><p class="hint">fixture実行とruntime経由は別表示。model・token usageの未取得を0として扱わない。合成fixtureの合格は人による実用確認を意味しない。</p></section>
{{range .Cases}}<article class="case" id="case-{{.ID}}"><div class="case-head"><h2>{{.ID}}</h2><div class="change {{changeClass .}}">{{change .}}</div></div><div class="source"><span class="tag">{{label .Source.AnnotationStatus}}</span><dl><dt>Raw object</dt><dd><code>{{.Source.ObjectID}}</code></dd><dt>SHA-256</dt><dd><code>{{.Source.SHA256}}</code></dd><dt>出典</dt><dd>{{.Source.URI}}</dd></dl><details><summary>評価に使った入力を確認</summary><pre>{{.Source.Input}}</pre></details></div><div class="grid"><section class="side"><h3>現行</h3>{{template "attempt" .Current}}</section><section class="side"><h3>候補</h3>{{template "attempt" .Candidate}}</section></div></article>{{else}}<section class="box"><p>このmanifestにはcaseがありません。評価精度や改善を判断できません。</p></section>{{end}}
<footer class="hint"><p>生成元のrun／dataset releaseを正本とする。出力内のHTML・script・外部resourceは文字列として表示する。採用は人が評価根拠を確認して行う。</p></footer></main></body></html>
{{define "attempt"}}{{if .}}<div class="state {{.Evaluation.Status}}">{{label .Evaluation.Status}}</div><dl><dt>実行状態</dt><dd>{{.State}}</dd><dt>待機・失敗理由</dt><dd>{{if .Reason}}{{.Reason}}{{else}}—{{end}}</dd><dt>Attempt</dt><dd><code>{{.ID}}</code></dd><dt>Run</dt><dd><code>{{.RunID}}</code></dd><dt>Model</dt><dd>{{model .}}</dd><dt>Token usage</dt><dd>{{if .Usage}}input {{.Usage.InputTokens}} / output {{.Usage.OutputTokens}}{{else}}未取得{{end}}</dd></dl>{{if .Evaluation.Reasons}}<ul>{{range .Evaluation.Reasons}}<li>{{.}}</li>{{end}}</ul>{{end}}{{if .Evaluation.Checks}}<details><summary>評価器のcheckを確認</summary><ul>{{range $name,$ok := .Evaluation.Checks}}<li>{{if $ok}}✓{{else}}×{{end}} {{$name}}</li>{{end}}</ul></details>{{end}}<h4>出力</h4><pre>{{.Output}}</pre>{{else}}<div class="state missing">結果未記録</div><p>未実行・未保存の可能性があるため、合否や改善として数えない。</p>{{end}}{{end}}`
